import React, { useState } from 'react';
import {
  Typography, Paper, Button, Table, TableBody, TableCell,
  TableContainer, TableHead, TableRow, IconButton, Chip, Box
} from '@mui/material';
import { Edit, Delete } from '@mui/icons-material';

const SupervisorsManagement = () => {
  const [supervisors] = useState([
    { id: '1', name: 'Juan Pérez', email: 'juan@empresa.com', areas: ['Producción', 'Calidad'], operators: 5 },
    { id: '2', name: 'María García', email: 'maria@empresa.com', areas: ['Seguridad'], operators: 3 }
  ]);

  return (
    <Box>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 3 }}>
        <Typography variant="h4">
          Gestión de Supervisores
        </Typography>
        <Button variant="contained">
          Nuevo Supervisor
        </Button>
      </Box>

      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>Nombre</TableCell>
              <TableCell>Email</TableCell>
              <TableCell>Áreas</TableCell>
              <TableCell>Operadores</TableCell>
              <TableCell>Acciones</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {supervisors.map((supervisor) => (
              <TableRow key={supervisor.id}>
                <TableCell>{supervisor.name}</TableCell>
                <TableCell>{supervisor.email}</TableCell>
                <TableCell>
                  {supervisor.areas.map(area => (
                    <Chip key={area} label={area} size="small" sx={{ mr: 1, mb: 1 }} />
                  ))}
                </TableCell>
                <TableCell>{supervisor.operators}</TableCell>
                <TableCell>
                  <IconButton color="primary">
                    <Edit />
                  </IconButton>
                  <IconButton color="error">
                    <Delete />
                  </IconButton>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>
    </Box>
  );
};

export default SupervisorsManagement;
